import{z as l,x as D,o as i,c as h,q as r,j as s,D as E,d as e,s as n,S as o,b as c}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"bcache","description":"","frontmatter":{"title":"bcache","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bcache.md","filePath":"cs/bcache.md","lastUpdated":1791413859000}'),A={name:"cs/bcache.md"};function p(b,a,B,d,S,m){const t=D("Mermaid");return i(),h("div",null,[a[2]||(a[2]=r('<h1 id="bcache" tabindex="-1">bcache <a class="header-anchor" href="#bcache" aria-label="Permalink to &quot;bcache&quot;">​</a></h1><div class="epigraph"><p>bcache 用一块快设备做慢设备的块缓存：写回或写通，命中则不必再走 HDD 臂。</p><footer>—— 据 Linux bcache 文档；Kent Overstreet 对 bcache 的设计讨论</footer></div><p><a href="/cs/thin-provisioning">上一课</a>省的是容量。延迟仍可以是 HDD。<a href="/cs/page-cache">页缓存</a> 是内存；重启丢失。缺口是 <strong>块层持久缓存</strong>：bcache（及后来的 bcachefs 不在本课）把 SSD 接到 HDD 前面。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>热数据若能停在 SSD，顺序冷数据留在大盘。bcache：backing + cache 设备，注册后出现 <code>/dev/bcacheN</code>。模式：writeback（写先进缓存，标脏）与 writethrough（写双份）。缺口：缓存未命中的绕过顺序流（顺序大写可绕过以免打满 SSD）；脏数据崩溃要用缓存超级块恢复；与 <a href="/cs/device-mapper-lvm">dm</a> 的 dm-cache 是同类对象，课序以 bcache 为实例。</p><p><span class="marginnote">缓存集可服务多个 backing。丢 SSD 在 writeback 下等于丢脏数据，要用附件或接受损失。本课不把 bcachefs 文件系统写成同一课。</span></p><p><span class="marginnote">术语翻译：writethrough（写通）是「写的时候两边都写」，慢但随时安全；writeback（写回）是「先写进快的 SSD 就回话，慢盘以后再补」——快在少等一次慢盘，风险是回写之前掉电，数据只存在于 SSD 上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读：查缓存桶（bucket）与 btree 索引，命中则从 SSD 填 bio，否则读 HDD 并可提升。写 writeback：写 SSD，完成上层，稍后回写 HDD。对照 FS 预读：预读仍发生在 bcache 之上或之下，取决于谁看到顺序。对照 RAID：缓存不是冗余。</p>',9)),(i(),s(o,null,{default:E(()=>[n(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20BIO%5B%22bio%22%5D%20--%3E%20BC%5B%22bcache%22%5D%0A%20%20BC%20--%3E%7C%22%E5%91%BD%E4%B8%AD%22%7C%20SSD%5B%22%E7%BC%93%E5%AD%98%E7%9B%98%22%5D%0A%20%20BC%20--%3E%7C%22bypass%2Fmiss%22%7C%20HDD%5B%22backing%22%5D%0A%20%20WB%5B%22writeback%20%E8%84%8F%22%5D%20--%3E%20HDD%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=c("h2",{id:"机制",tabindex:"-1"},[e("机制 "),c("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=c("p",null,[e("bcache 把「存储分层」放进块层，FS 无需知道。它与 CPU cache 同构只在「命中/缺失」口号上；一致性是脏桶与回写，不是 MESI。不要写成硬件预取课。与 "),c("a",{href:"/cs/thin-provisioning"},"精简"),e("：可叠，监控更乱。")],-1)),a[5]||(a[5]=c("p",null,"错误：缓存只读降级、只通盘，是运维模式；课序要求理解脏数据依赖缓存盘。",-1)),(i(),s(o,null,{default:E(()=>[n(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%BA%94%E7%94%A8%E5%86%99%E5%9D%97%20X%2C%20writeback%20%E6%A8%A1%E5%BC%8F%22%5D%20--%3E%20S%5B%22%E5%86%99%E5%85%A5%20SSD%20%E7%BC%93%E5%AD%98%E6%A1%B6%2C%20%E6%A0%87%E8%84%8F%22%5D%0A%20%20S%20--%3E%20ACK%5B%22%E7%AB%8B%E5%8D%B3%E5%90%91%E4%B8%8A%E5%B1%82%E8%BF%94%E5%9B%9E%E5%AE%8C%E6%88%90%22%5D%0A%20%20ACK%20--%3E%20CRASH%7B%22%E5%9B%9E%E5%86%99%E5%89%8D%E6%8E%89%E7%94%B5%3F%22%7D%0A%20%20CRASH%20--%3E%7C%22%E6%98%AF%22%7C%20REC%5B%22%E9%87%8D%E5%90%AF%E5%90%8E%E7%85%A7%E8%B6%85%E7%BA%A7%E5%9D%97%E4%B8%8E%E5%85%83%E6%95%B0%E6%8D%AE%E6%89%BE%E5%9B%9E%E8%84%8F%E6%A1%B6%22%5D%0A%20%20CRASH%20--%3E%7C%22%E5%90%A6%22%7C%20LATER%5B%22%E5%9B%9E%E5%86%99%E7%BA%BF%E7%A8%8B%E7%A8%8D%E5%90%8E%E6%8C%91%E8%84%8F%E6%A1%B6%22%5D%0A%20%20LATER%20--%3E%20FLUSH%5B%22%E6%8A%8A%E8%84%8F%E6%95%B0%E6%8D%AE%E5%86%99%E5%9B%9E%20HDD%22%5D%0A%20%20FLUSH%20--%3E%20CLR%5B%22%E6%B8%85%E8%84%8F%E6%A0%87%E8%AE%B0%2C%20%E6%A1%B6%E8%85%BE%E5%87%BA%E6%9D%A5%E5%A4%8D%E7%94%A8%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">直觉类比：writeback 像收银台先给小票、账目下班再抄进总账——顾客不用等抄账，体验快；但总账抄完前失火，只能照小票补账。bcache 崩溃恢复做的就是「照小票补账」：靠 SSD 上的脏桶与元数据把没落到 HDD 的写找回来。</span></p><p>实现上：writeback 模式丢缓存盘等于丢尚未回写的数据，要按电池或副本设计。顺序绕过阈值调错会让 SSD 被大备份打满，命中率崩。 读法上只引用<a href="/cs/thin-provisioning">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p><span class="marginnote">数字实例：HDD 一次随机读约 10 ms（寻道加旋转），SATA SSD 约 0.1 ms，相差百倍；若 80% 的读命中缓存，平均延迟约 \\(0.8 \\times 0.1 + 0.2 \\times 10 \\approx 2\\) ms。命中率提到 95% 后降到约 0.6 ms——「热数据停在 SSD」直接兑现成延迟。</span></p><p>本课在操作系统进阶的「存储栈 / 块层到设备」课序里，对象是 <strong>bcache</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 EnhanceIO、Lvmcache 的参数对照表。不保证 NVMe 对 NVMe 再套 bcache 有益。下一课缓存都不经过：DAX 把持久内存直接映射进页表。</p><p>版本字段会变，课序钉的是机制对象「bcache」，不是某一主线内核的结构体名。 后课默认：块层可用 SSD 缓存 HDD。持久内存如何绕过块层进 CPU 缓存，下一课 DAX。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>bcache 用快设备缓存慢设备；writeback 有脏。</li><li>顺序流可绕过以免污染缓存。</li><li>DAX 与持久内存是下一课。</li><li>出处：Linux bcache；dm-cache 对照；<em>OSTEP</em> I/O 栈。</li></ul>',10))])}const f=l(A,[["render",p]]);export{u as __pageData,f as default};
